// conformance_test.go verifies that the relay protocol implementation
// round-trips each golden frame vector exactly. A json-tag rename, field
// addition, or encoding change on either side of the wire contract causes an
// immediate test failure.
//
// Vectors are loaded from contracts/protocol/v1/vectors.json, which is
// generated by cmd/gen-vectors. Regenerate when protocol.go changes:
//
//	go run ./cmd/gen-vectors > contracts/protocol/v1/vectors.json
package protocol

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

// vectorFile mirrors the structure of contracts/protocol/v1/vectors.json.
type vectorFile struct {
	SchemaVersion int            `json:"schema_version"`
	Carriers      []string       `json:"carriers"`
	Vectors       []goldenVector `json:"vectors"`
}

type goldenVector struct {
	Name         string `json:"name"`
	Description  string `json:"description"`
	Struct       Frame  `json:"struct"`
	WireBytesHex string `json:"wire_bytes_hex"`
}

// vectorsPath returns the absolute path to vectors.json relative to the
// package source directory. Go test CWD is the package directory.
func vectorsPath(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	// file is .../internal/protocol/conformance_test.go
	// vectors.json is at .../contracts/protocol/v1/vectors.json
	repoRoot := filepath.Join(filepath.Dir(file), "..", "..")
	return filepath.Join(repoRoot, "contracts", "protocol", "v1", "vectors.json")
}

func loadVectors(t *testing.T) vectorFile {
	t.Helper()
	path := vectorsPath(t)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("load golden vectors %s: %v", path, err)
	}
	var vf vectorFile
	if err := json.Unmarshal(data, &vf); err != nil {
		t.Fatalf("parse golden vectors: %v", err)
	}
	return vf
}

// TestConformanceDecodeGolden verifies that ReadFrame produces the expected
// struct for every golden wire vector.
func TestConformanceDecodeGolden(t *testing.T) {
	vf := loadVectors(t)
	for _, v := range vf.Vectors {
		v := v
		t.Run(v.Name+"/decode", func(t *testing.T) {
			wire, err := hex.DecodeString(v.WireBytesHex)
			if err != nil {
				t.Fatalf("decode hex: %v", err)
			}
			got, err := ReadFrame(bytes.NewReader(wire))
			if err != nil {
				t.Fatalf("ReadFrame: %v", err)
			}
			// Re-marshal both to canonical JSON for comparison (avoids
			// pointer equality issues with nested structs).
			gotJSON, _ := json.Marshal(got)
			wantJSON, _ := json.Marshal(v.Struct)
			if !bytes.Equal(gotJSON, wantJSON) {
				t.Errorf("decoded struct mismatch:\n  got  %s\n  want %s", gotJSON, wantJSON)
			}
		})
	}
}

// TestConformanceEncodeGolden verifies that WriteFrame produces the exact golden
// wire bytes for every golden struct. Any json-tag drift causes this to fail.
func TestConformanceEncodeGolden(t *testing.T) {
	vf := loadVectors(t)
	for _, v := range vf.Vectors {
		v := v
		t.Run(v.Name+"/encode", func(t *testing.T) {
			want, err := hex.DecodeString(v.WireBytesHex)
			if err != nil {
				t.Fatalf("decode hex: %v", err)
			}
			var buf bytes.Buffer
			if err := WriteFrame(&buf, v.Struct); err != nil {
				t.Fatalf("WriteFrame: %v", err)
			}
			if !bytes.Equal(buf.Bytes(), want) {
				t.Errorf("encoded bytes mismatch:\n  got  %x\n  want %x", buf.Bytes(), want)
			}
		})
	}
}
